"""Build vocabbot.pyz, the generated files of the plugin, and the release packages.

    python scripts/build.py pyz [--out build/vocabbot.pyz]
    python scripts/build.py skills            write the generated files of every skill
    python scripts/build.py skills --check    exit 1 when a generated file is stale
    python scripts/build.py package           dist/: wheel, sdist, pyz, plugin, skill zips

`vocabbot.pyz` holds src/vocabbot without compiled files and a __main__.py that
returns the program's exit code; it runs with `python vocabbot.pyz <command>`.
Entries are sorted and carry a fixed time, so the same sources give the same
archive. Every skill gets a copy in bin/, together with shared/rules.md (from
rules/*.md) and shared/labels.md (from the Polish texts of the engine), and
the plugin gets copies of LICENSE and NOTICE. The check compares the contents
of every file, so it does not depend on the zlib of the machine.
"""

from __future__ import annotations

import argparse
import hashlib
import io
import json
import shutil
import subprocess
import sys
import zipfile
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
SOURCE = REPO / "src" / "vocabbot"
RULES = REPO / "rules"
PLUGIN = REPO / "plugin"
SKILLS = PLUGIN / "skills"
DIST = REPO / "dist"
MAIN = "import sys\n\nfrom vocabbot.cli import main\n\nsys.exit(main())\n"
SHEBANG = b"#!/usr/bin/env python3\n"
FIXED_TIME = (1980, 1, 1, 0, 0, 0)
SKIP_PARTS = {"__pycache__", ".DS_Store", "Thumbs.db", "desktop.ini"}
GENERATED = "<!-- GENERATED by scripts/build.py from {source}; edit the source, not this copy -->"
# frontmatter keys a single-skill upload to claude.ai accepts
UPLOAD_KEYS = {"name", "description", "license", "compatibility", "metadata", "allowed-tools"}


def files_under(root: Path) -> list[Path]:
    return sorted(
        p
        for p in root.rglob("*")
        if p.is_file() and not SKIP_PARTS.intersection(p.parts) and p.suffix != ".pyc"
    )


# ---------------------------------------------------------------- the engine file


def pyz_members() -> dict[str, bytes]:
    """Every file of the archive by its name inside the archive."""
    members = {
        "vocabbot/" + path.relative_to(SOURCE).as_posix(): path.read_bytes()
        for path in files_under(SOURCE)
    }
    members["__main__.py"] = MAIN.encode("utf-8")
    return dict(sorted(members.items()))


def pyz_bytes() -> bytes:
    buffer = io.BytesIO()
    buffer.write(SHEBANG)
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for name, data in pyz_members().items():
            info = zipfile.ZipInfo(name, FIXED_TIME)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = (0o100644 & 0xFFFF) << 16
            archive.writestr(info, data)
    return buffer.getvalue()


def pyz_is_current(path: Path, expected: dict[str, bytes]) -> bool:
    """The archive holds exactly the expected files with the expected contents."""
    try:
        with zipfile.ZipFile(path) as archive:
            names = sorted(archive.namelist())
            if names != sorted(expected):
                return False
            return all(archive.read(name) == expected[name] for name in names)
    except (OSError, zipfile.BadZipFile):
        return False


def build_pyz(out: Path) -> Path:
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(pyz_bytes())
    return out


# ---------------------------------------------------------------- generated skill files


def rules_text() -> str:
    parts = [GENERATED.format(source="rules/*.md"), "", "# VocabBot rules", ""]
    parts.append("Every VocabBot skill keeps these rules. They come before the skill's own steps.")
    for path in sorted(RULES.glob("*.md")):
        parts += ["", path.read_text(encoding="utf-8").strip()]
    return "\n".join(parts) + "\n"


def labels_text() -> str:
    texts = json.loads((SOURCE / "data" / "i18n" / "pl.json").read_text(encoding="utf-8"))
    lines = [
        GENERATED.format(source="src/vocabbot/data/i18n/pl.json"),
        "",
        "# Labels in Polish",
        "",
        "The engine's codes and the words the learner reads for them.",
    ]
    for key, title in (
        ("grades", "Grades (`grade`)"),
        ("error_classes", "Error classes (`errors`)"),
        ("pos", "Parts of speech (`pos`)"),
        ("genders", "Genders (`gender`)"),
        ("forms", "Forms (`forms`)"),
        ("phases", "Phases (`phase`)"),
    ):
        lines += ["", f"## {title}", "", "| Code | Polish |", "|---|---|"]
        lines += [f"| `{code}` | {label} |" for code, label in texts[key].items()]
    return "\n".join(lines) + "\n"


def expected_files() -> dict[Path, bytes]:
    """Generated text files of the plugin, by path."""
    out: dict[Path, bytes] = {
        PLUGIN / "LICENSE": (REPO / "LICENSE").read_bytes(),
        PLUGIN / "NOTICE": (REPO / "NOTICE").read_bytes(),
    }
    rules = rules_text().encode("utf-8")
    labels = labels_text().encode("utf-8")
    for skill in skill_folders():
        out[skill / "shared" / "rules.md"] = rules
        out[skill / "shared" / "labels.md"] = labels
    return out


def skill_folders() -> list[Path]:
    return sorted(p for p in SKILLS.iterdir() if (p / "SKILL.md").is_file())


def stale_files() -> list[str]:
    """Generated files that are missing, different, or left over in shared/ and bin/."""
    stale = [
        path.relative_to(REPO).as_posix()
        for path, data in expected_files().items()
        if not path.is_file() or path.read_bytes() != data
    ]
    members = pyz_members()
    for skill in skill_folders():
        target = skill / "bin" / "vocabbot.pyz"
        if not pyz_is_current(target, members):
            stale.append(target.relative_to(REPO).as_posix())
        for folder, allowed in (("shared", {"rules.md", "labels.md"}), ("bin", {"vocabbot.pyz"})):
            for extra in (skill / folder).glob("*"):
                if extra.name not in allowed:
                    stale.append(extra.relative_to(REPO).as_posix())
    return stale


def write_skills() -> list[str]:
    written = []
    for path, data in expected_files().items():
        if not path.is_file() or path.read_bytes() != data:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            written.append(path.relative_to(REPO).as_posix())
    archive = pyz_bytes()
    members = pyz_members()
    for skill in skill_folders():
        target = skill / "bin" / "vocabbot.pyz"
        if not pyz_is_current(target, members):
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive)
            written.append(target.relative_to(REPO).as_posix())
    return written


# ---------------------------------------------------------------- release packages


def upload_frontmatter(text: str) -> str:
    """SKILL.md for a single-skill upload: frontmatter keys outside UPLOAD_KEYS are left out."""
    lines = text.split("\n")
    if not lines or lines[0].strip() != "---":
        return text
    end = next(i for i in range(1, len(lines)) if lines[i].strip() == "---")
    kept, keep = [], True
    for line in lines[1:end]:
        if line and not line[0].isspace():
            keep = line.split(":", 1)[0].strip() in UPLOAD_KEYS
        if keep:
            kept.append(line)
    return "\n".join([lines[0], *kept, *lines[end:]])


def write_zip(target: Path, root: Path, prefix: str = "", for_upload: bool = False) -> int:
    target.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with zipfile.ZipFile(target, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files_under(root):
            info = zipfile.ZipInfo(prefix + path.relative_to(root).as_posix(), FIXED_TIME)
            info.compress_type = zipfile.ZIP_DEFLATED
            mode = 0o755 if path.suffix in (".py", ".pyz", ".sh") else 0o644
            info.external_attr = (0o100000 | mode) << 16
            data = path.read_bytes()
            if for_upload and path.name == "SKILL.md" and path.parent == root:
                data = upload_frontmatter(data.decode("utf-8")).encode("utf-8")
            archive.writestr(info, data)
            count += 1
    return count


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def package(out: Path, skip_checks: bool) -> dict[str, object]:
    if not skip_checks:
        for cmd in (
            [sys.executable, "scripts/build.py", "skills", "--check"],
            [sys.executable, "scripts/validate.py"],
        ):
            done = subprocess.run(cmd, cwd=REPO, capture_output=True, text=True, encoding="utf-8")
            if done.returncode:
                sys.stderr.write(done.stdout[-3000:] + done.stderr[-3000:])
                raise SystemExit(f"refusing to package: {' '.join(cmd[1:])} failed")
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True)
    uv = shutil.which("uv")
    if uv is None:
        raise SystemExit("uv is needed for the wheel and the sdist")
    subprocess.run([uv, "build", "--out-dir", str(out), "--no-progress"], cwd=REPO, check=True)
    manifest = json.loads((PLUGIN / ".claude-plugin" / "plugin.json").read_text("utf-8"))
    name = manifest["name"]
    build_pyz(out / "vocabbot.pyz")
    write_zip(out / f"{name}.plugin", PLUGIN)
    for skill in skill_folders():
        write_zip(out / "skills" / f"{skill.name}.zip", skill, skill.name + "/", for_upload=True)
    files = sorted(
        p
        for p in out.rglob("*")
        if p.is_file() and p.name != "SHA256SUMS" and not p.name.startswith(".")
    )
    sums = "".join(f"{sha256(p)}  {p.relative_to(out).as_posix()}\n" for p in files)
    (out / "SHA256SUMS").write_bytes(sums.encode("utf-8"))
    return {
        "version": manifest["version"],
        "files": {p.relative_to(out).as_posix(): p.stat().st_size for p in files},
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=(__doc__ or "").split("\n")[0])
    sub = parser.add_subparsers(dest="target", required=True)
    pyz = sub.add_parser("pyz", help="build vocabbot.pyz")
    pyz.add_argument("--out", type=Path, default=REPO / "build" / "vocabbot.pyz")
    skills = sub.add_parser("skills", help="write the generated files of the plugin")
    skills.add_argument("--check", action="store_true", help="only report stale files")
    pack = sub.add_parser("package", help="build the release packages into dist/")
    pack.add_argument("--out", type=Path, default=DIST)
    pack.add_argument("--skip-checks", action="store_true")
    args = parser.parse_args(argv)
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    if args.target == "pyz":
        path = build_pyz(args.out)
        print(f"{path} ({path.stat().st_size // 1024} KiB)")
        return 0
    if args.target == "skills":
        if args.check:
            stale = stale_files()
            print(json.dumps({"stale": stale}, indent=1))
            return 1 if stale else 0
        written = write_skills()
        print(json.dumps({"written": written}, indent=1))
        return 0
    print(json.dumps(package(args.out, args.skip_checks), indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(main())
